entries[118310] = { ["name"] = "Recipe Idea: Hearty Elekk Steak", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Hearty Elekk Steak.\nRecipe for 4 servings. Actual number of servings will vary based on cooking skill. You may get a new recipe idea while cooking.\nRequires Draenor Cooking (1)\n\nHearty Elekk Steak\nUse: Restores 8173 health and ( 2125 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 14 stamina for 1 hour.\n\nBy tasting this dish, you might obtain the recipe.\nSell Price:\nRequires Raw Elekk Meat (5)" }
entries[118311] = { ["name"] = "Recipe Idea: Blackrock Ham", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Blackrock Ham.\nRecipe for 4 servings. Actual number of servings will vary based on cooking skill. You may get a new recipe idea while cooking.\nRequires Draenor Cooking (1)\n\nBlackrock Ham\nUse: Restores 8173 health and ( 2125 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 6 Critical Strike for 1 hour.\n\nBy tasting this dish, you might obtain the recipe.\nSell Price:\nRequires Raw Boar Meat (5)" }
