entries[118416] = { ["name"] = "Fish Roe", ["text"] = "Use: Restores 8173 health and ( 2125 / 5 * 20) mana over 20 sec. If you spend at least 10 seconds eating you will become well fed and gain 6 in a stat for 1 hour. May benefit some more than others.\nSell Price:" }
entries[118417] = { ["name"] = "Crate of Surplus Materials", ["text"] = "Quest Item\n\"Filled with nails, blankets, and other random items that were sitting around.\"" }
