entries[118425] = { ["name"] = "Nesingwary's Lost Horn", ["text"] = "Ashran\nBinds when picked up\nUse: Summons a stampede of beasts to charge through the Road of Glory, knocking enemies into the air and dealing Physical damage.\n\nCan only be used in the Road of Glory within Ashran. (1 Hour Cooldown)\n\"H.W. is etched on the side of this horn.\"" }
entries[118426] = { ["name"] = "Scroll of Invoke Yu'lon, the Jade Serpent", ["text"] = "Ashran\nBinds when picked up\nUse: Invokes the Jade Serpent Celestial in the Road of Glory, healing all friendly targets to full health and removing all Magical, Poison, and Disease effects.\n\nCan only be used in the Road of Glory within Ashran. (1 Hour Cooldown)\n\"Fei is written on the side of this satchel.\"" }
entries[118427] = { ["name"] = "Autographed Hearthstone Card", ["text"] = "Toy\nUse: Turn the card over to see what you got! (10 Sec Cooldown)\n\"Signed by Trump and Reckful. Not too shabby.\"\nSell Price:" }
entries[118428] = { ["name"] = "Legion Chili", ["text"] = "Use: Restores 8173 health and ( 2125 / 5 * 20) mana over 20 sec. If you spend at least 10 seconds eating you will become well fed and gain 10 in a stat for 1 hour.\n\"It burns.\"\nSell Price:" }
