entries[118458] = { ["name"] = "Formula: Enchant Weapon - Mark of the Thunderlord", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to permanently enchant a melee weapon to sometimes increase critical strike.\nPermanently enchants a melee weapon to sometimes increase your critical strike by 77 for 6 sec. While active, critical heals and attacks may extend the duration.\n\nCannot be applied to items above level 376.\nRequires Draenor Enchanting (1)" }
entries[118459] = { ["name"] = "Formula: Enchant Weapon - Mark of the Shattered Hand", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to permanently enchant a melee weapon to sometimes bleed your enemy.\nPermanently enchants a melee weapon to sometimes bleed your enemy for 75 damage, plus an additional 225 damage over 6 sec.\n\nCannot be applied to items above level 376.\nRequires Enchanting (1)\nSell Price:" }
entries[118460] = { ["name"] = "Formula: Enchant Weapon - Mark of Warsong", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to permanently enchant a melee weapon to sometimes increase haste.\nPermanently enchants a melee weapon to sometimes increase haste by ( 15 * 10), diminishing by 10% every 2 sec.\n\nCannot be applied to items above level 376.\nRequires Draenor Enchanting (1)" }
entries[118461] = { ["name"] = "Formula: Enchant Weapon - Mark of the Frostwolf", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to permanently enchant a melee weapon to sometimes increases critical strike.\nPermanently enchants a melee weapon to sometimes increase critical strike by 77 for 6 sec. Effect can stack 2 times.\n\nCannot be applied to items above level 376.\nRequires Draenor Enchanting (1)" }
entries[118462] = { ["name"] = "Formula: Enchant Weapon - Mark of Shadowmoon", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to permanently enchant a melee weapon to sometimes increase Versatility.\nPermanently enchants a melee weapon to sometimes increase Versatility by 77 for 15 sec.\n\nCannot be applied to items above level 376.\nRequires Draenor Enchanting (1)" }
entries[118463] = { ["name"] = "Formula: Enchant Weapon - Mark of Blackrock", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to permanently enchant a melee weapon to sometimes increase bonus armor.\nPermanently enchants a melee weapon to sometimes increase Versatility by 77 for 12 sec. Effect can only occur when you are below 60% health.\n\nCannot be applied to items above level 376.\nRequires Draenor Enchanting (1)" }
entries[118464] = { ["name"] = "Formula: Temporal Shatter", ["text"] = "Binds when picked up\nUse: Teaches you how to permanently enchant a ring to increase critical strike by 112.\nRequires Enchanting (600)\nSell Price:" }
entries[118465] = { ["name"] = "Formula: Luminous Shatter", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to permanently enchant a ring to increase critical strike by 112.\nRequires Enchanting (1)\nSell Price:\nLuminous Shard\nCrafting Reagent\nRequires Draenic Dust (20)" }
entries[118466] = { ["name"] = "Formula: Azurian Shards", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to create Azurian Shards.\nLow Enchanting skill may fracture the crystal when created.\n\nMay also create Sorcerous Air and Fire.\n\nCooldown resets daily.\nRequires Enchanting (600)\nSell Price:\nTemporal Crystal\nCrafting Reagent\nRequires Luminous Shard" }
entries[118467] = { ["name"] = "Formula: Enchant Weapon - Mark of Bleeding Hollow", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to permanently enchant a melee weapon to sometimes increase mastery.\nPermanently enchants a melee weapon to sometimes increase mastery by 77 for 12 sec.\n\nCannot be applied to items above level 376.\nRequires Draenor Enchanting (1)" }
entries[118468] = { ["name"] = "Fresh Bread", ["text"] = "Quest Item\n\"Baros would appreciate this.\"" }
entries[118469] = { ["name"] = "Black Claw of Sethe", ["text"] = "Binds when picked up\n\"Drips endlessly with an eerie, dark substance. Your mounts-in-training are unnerved by this item.\"" }
entries[118470] = { ["name"] = "Garn-Tooth Necklace", ["text"] = "Binds when picked up\n\"Smells like a wolf pack. Your mounts-in-training are very unnerved by this item.\"" }
entries[118471] = { ["name"] = "Salvaged Parts", ["text"] = "Quest Item\n\"Some are good to re-use, but not many.\"" }
entries[118472] = { ["name"] = "Savage Blood", ["text"] = "Crafting Reagent\n\"Obtained through the Garrison Barn, or crafted by alchemists. Can be bought and sold on the auction house.\"\nSell Price:" }
entries[118473] = { ["name"] = "Small Sack of Salvaged Goods", ["text"] = "Binds when picked up\nUse: Dig through the sack to search for anything useful. Only available at your Salvage Yard." }
entries[118474] = { ["name"] = "Supreme Manual of Dance", ["text"] = "Binds when picked up\nUse: Teaches a follower the Dancer trait. Another trait will be lost in the process.\n\"All a follower needs to know about smooth moves - Johnny Castle\"\nSell Price:" }
entries[118475] = { ["name"] = "Hearthstone Strategy Guide", ["text"] = "Binds when picked up\nUse: Teaches a follower the Hearthstone Pro trait. Another trait will be lost in the process.\n\"Transforms an ordinary follower into a tactical genius.\"\nSell Price:" }
entries[118476] = { ["name"] = "Schematic: Shrediron's Shredder", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Shrediron's Shredder.\nRequires Draenor Engineering (1)\nSell Price:\nShrediron's Shredder\nBinds when equipped\nUnique-Equipped: Warlords Crafted (3)\nRanged Gun\n7 - 13 Damage Speed 3.00\n(3.3 damage per second)\n+5 Agility\n+7 Stamina\nDurability 120 / 120\n\"To engineers, a work of art. To hunters, a tool for the art of killing.\"\nSell Price:\nRequires Gearspring Parts (100)\nOptional Reagents: Optional Reagent Slot (#50) , True Iron Trigger (#239)" }
entries[118477] = { ["name"] = "Schematic: Oglethorpe's Missile Splitter", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Oglethorpe's Missile Splitter.\nRequires Draenor Engineering (1)\nSell Price:\nOglethorpe's Missile Splitter\nUse: Permanently attaches a special device to a ranged weapon, sometimes increases haste by 115 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound. Cannot be applied to items above level 320.\nSell Price:\nRequires Gearspring Parts (20)" }
entries[118478] = { ["name"] = "Schematic: Megawatt Filament", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Megawatt Filament.\nRequires Draenor Engineering (1)\nSell Price:\nMegawatt Filament\nUse: Permanently attaches an electrified device to a ranged weapon, sometimes increasing Critical Strike by 115 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound. Cannot be applied to items above level 320.\n\"Everything is better when it's electrified.\"\nSell Price:\nRequires Gearspring Parts (20)" }
entries[118479] = { ["name"] = "Schematic: Goblin Glider Kit", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Goblin Glider Kit.\nRequires Engineering (1)\nSell Price:\nGoblin Glider Kit\nUse: Reduces your falling speed for 2 min. (3 Min Cooldown)\nSell Price:\nRequires True Iron Ore (8), Sumptuous Fur (5)" }
entries[118480] = { ["name"] = "Schematic: Findle's Loot-a-Rang", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Findle's Loot-a-Rang.\nRequires Draenor Engineering (1)\nSell Price:\nFindle's Loot-A-Rang\nBinds when used\nToy\nUse: Retrieves the loot from a nearby corpse. Can only be used in Draenor. (3 Sec Cooldown)\nSell Price:\nRequires Gearspring Parts (50)" }
entries[118481] = { ["name"] = "Schematic: World Shrinker", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a World Shrinker.\nRequires Draenor Engineering (1)\nSell Price:\nWorld Shrinker\nToy\nUse: Shrinks the entire world for 5 min or until you attack. (15 Min Cooldown)\nRequires Draenor Engineering (1)\n\"Overuse may result in permanent shrinkage.\"\nSell Price:\nRequires Gearspring Parts (50)" }
entries[118482] = { ["name"] = "Schematic: Stealthman 54", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Stealthman 54.\nRequires Engineering (1)\nSell Price:\nStealthman 54\nUse: Cloaks the user in a stealth field for as long as they stand still. Cannot be used in combat. The field lasts for up to 6 sec. after moving.\n\nThe Stealthman shares a cooldown with non-healing potions. Ineffective above level 49. (5 Min Cooldown)\n\"Invisibility is for suckers!\"\nSell Price:\nRequires Blackrock Ore (2), True Iron Ore (2), Nagrand Arrowbloom (2)" }
entries[118483] = { ["name"] = "Schematic: Ultimate Gnomish Army Knife", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make an Ultimate Gnomish Army Knife.\nRequires Engineering (1)\nSell Price:\nUltimate Gnomish Army Knife\n+10 Draenor Mining Skill.\n+10 Draenor Herbalism Skill.\n+10 Draenor Skinning Skill.\n\"Includes every profession tool.\"\nSell Price:\nRequires Gearspring Parts (5)" }
entries[118484] = { ["name"] = "Schematic: Mechanical Axebeak", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Mechanical Axebeak.\nRequires Draenor Engineering (1)\nSell Price:\nMechanical Axebeak\nUse: Teaches you how to summon this companion.\nSummons and dismisses your Mechanical Axebeak.\nRequires level 1 to 80 ( 80)\nSell Price:\nRequires Gearspring Parts (50)" }
entries[118485] = { ["name"] = "Schematic: Lifelike Mechanical Frostboar", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Lifelike Mechanical Frostboar.\nRequires Draenor Engineering (1)\nSell Price:\nLifelike Mechanical Frostboar\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your lifelike mechanical boar.\nRequires level 1 to 80 ( 80)\nSell Price:\nRequires Gearspring Parts (50), Sumptuous Fur (40)" }
entries[118486] = { ["name"] = "Schematic: Blackrock Seaforium", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Blackrock Seaforium.\nRequires Engineering (1)\nSell Price:" }
entries[118487] = { ["name"] = "Schematic: Personal Hologram", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Personal Hologram.\nRequires Draenor Engineering (1)\nSell Price:\nPersonal Hologram\nBinds when used\nToy\nUse: Create a temporary hologram of yourself for 1 min. (5 Min Cooldown)\n\"Image may react to some emotes.\"\nSell Price:\nRequires Gearspring Parts (50)" }
entries[118488] = { ["name"] = "Schematic: Wormhole Centrifuge", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Wormhole Centrifuge.\nRequires Draenor Engineering (1)\nSell Price:\nWormhole Centrifuge\nBinds when used\nToy\nUse: Creates a spinning wormhole the Engineer can use to travel around Draenor. (4 Hrs Cooldown)\nRequires Draenor Engineering (1)\nSell Price:\nRequires Gearspring Parts (50)" }
entries[118489] = { ["name"] = "Schematic: Swapblaster", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Swapblaster.\nRequires Draenor Engineering (1)\nSell Price:\nSwapblaster\nBinds when used\nUse: Swaps your location with another party member. Cannot be used in combat. (1 Min Cooldown)\n\"Warning: Swapping with someone using a Neural Silencer is highly dangerous.\"\nSell Price:\nRequires Gearspring Parts (50), Temporal Crystal" }
entries[118490] = { ["name"] = "Schematic: Blingtron 5000", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Blingtron 5000.\nRequires Draenor Engineering (1)\nSell Price:\nBlingtron 5000\nBinds when picked up\nToy\nUse: Assembles the upgraded Blingtron 5000, a savage, yet generous, robot. While he will give out gifts to players once per day, he will also fight other Blingtron units to the death. (4 Hrs Cooldown)\nRequires Draenor Engineering (1)\nRequires Gearspring Parts (100)" }
entries[118491] = { ["name"] = "Schematic: Linkgrease Locksprocket", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Linkgrease Locksprocket.\nRequires Draenor Engineering (1)\nSell Price:\nLinkgrease Locksprocket\nRequires Gearspring Parts (70), Sorcerous Fire (15), Savage Blood (15)" }
entries[118492] = { ["name"] = "Schematic: Morden's Magnificent Contraption", ["text"] = "Binds when picked up\nUnique\nRequires Engineering (1)\n\"The writing on the recipe has faded.\"\nSell Price:" }
entries[118493] = { ["name"] = "Schematic: Didi's Delicate Assembly", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Didi's Delicate Assembly.\nRequires Draenor Engineering (1)\nSell Price:\nDidi's Delicate Assembly\nUse: Rerolls the secondary stats of an Engineered gun or goggles with item level 45 or below.\nRequires True Iron Ore (15), Blackrock Ore (15)" }
entries[118494] = { ["name"] = "Schematic: Gearspring Parts", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Gearspring Parts.\nAdditional parts are created when your Engineering skill is 600 or higher.\n\nMay also create Sorcerous Fire and Air.\n\nCooldown resets daily.\nRequires Engineering (1)\nSell Price:\nGearspring Parts\nBinds when picked up\nCrafting Reagent\n\"The ultimate in adaptability, these parts are revered by engineers creating or fixing complex devices.\"\nSell Price:\nRequires True Iron Ore (15), Blackrock Ore (15)" }
entries[118495] = { ["name"] = "Schematic: Hemet's Heartseeker", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Hemet's Heartseeker.\nRequires Draenor Engineering (1)\nSell Price:\nHemet's Heartseeker\nUse: Permanently attaches a superior scope to a ranged weapon, sometimes increasing mastery by 115 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound. Cannot be applied to items above level 320.\n\"If there's one thing Nesingwary knows how to improve, it's a killin' device.\"\nSell Price:\nRequires Gearspring Parts (20)" }
entries[118496] = { ["name"] = "Schematic: Mecha-Blast Rocket", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Mecha-Blast Rocket.\nRequires Engineering (1)\nSell Price:\nMecha-Blast Rocket\nUse: Deals ( 539 + 135 * 3) Fire damage to an enemy up to 40 yards away. (5 Min Cooldown)\nSell Price:\nRequires Blackrock Ore (6)" }
entries[118497] = { ["name"] = "Schematic: Cybergenetic Mechshades", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Cybergenetic Mechshades.\nRequires Draenor Engineering (1)\nSell Price:\nCybergenetic Mechshades\nBinds when equipped\nUnique-Equipped: Warlords Crafted (3)\nHead Mail\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\nDurability 100 / 100\nUse: Allows you to look far into the distance.\nRequires Draenor Engineering (1)\nSell Price:\nRequires Gearspring Parts (100)\nOptional Reagents: Optional Reagent Slot (#50) , Linkgrease Locksprocket (#238)" }
entries[118498] = { ["name"] = "Schematic: Night-Vision Mechshades", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Night-Vision Mechshades.\nRequires Draenor Engineering (1)\nSell Price:\nNight-Vision Mechshades\nBinds when equipped\nUnique-Equipped: Warlords Crafted (3)\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\nDurability 100 / 100\nUse: Allows you to look far into the distance.\nRequires Draenor Engineering (1)\nSell Price:\nRequires Gearspring Parts (100)\nOptional Reagents: Optional Reagent Slot (#50) , Linkgrease Locksprocket (#238)" }
entries[118499] = { ["name"] = "Schematic: Plasma Mechshades", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Plasma Mechshades.\nRequires Draenor Engineering (1)\nSell Price:\nPlasma Mechshades\nBinds when equipped\nUnique-Equipped: Warlords Crafted (3)\nHead Cloth\n3 Armor\n+5 Intellect\n+7 Stamina\nDurability 100 / 100\nUse: Allows you to look far into the distance.\nRequires Draenor Engineering (1)\nSell Price:\nRequires Gearspring Parts (100)\nOptional Reagents: Optional Reagent Slot (#50) , Linkgrease Locksprocket (#238)" }
entries[118500] = { ["name"] = "Schematic: Razorguard Mechshades", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Razorguard Mechshades.\nRequires Draenor Engineering (1)\nSell Price:\nRazorguard Mechshades\nBinds when equipped\nUnique-Equipped: Warlords Crafted (3)\nHead Plate\n13 Armor\n+5 [Strength or Intellect]\n+7 Stamina\nDurability 100 / 100\nUse: Allows you to look far into the distance.\nRequires Draenor Engineering (1)\nSell Price:\nRequires Gearspring Parts (100)\nOptional Reagents: Optional Reagent Slot (#50) , Linkgrease Locksprocket (#238)" }
